  function median(a) {
    if (!a.length) return null;
    var s = a.slice().sort(function (x, y) { return x - y; });
    var m = s.length >> 1;
    return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
  }

  // T1 rule (lowest repeatable time of standardized work): values rounded to the second (res 1) or to the tenth
  // (res 0.1); the smallest value is discarded (it can be an error); then the smallest value that repeats among the
  // remaining ones; without repetition, the smallest remaining.
  function roundTo(v, res) { return res === 0.1 ? Math.round(r3(v) * 10 + 1e-7) / 10 : Math.round(r3(v) + 1e-9); }
  function lowestRepeatable(values, res) {
    var r = [];
    for (var i = 0; i < values.length; i++) {
      var v = values[i];
      if (v != null && isFinite(v)) r.push(roundTo(v, res));
    }
    if (!r.length) return null;
    var s = r.slice().sort(function (a, b) { return a - b; });
    if (s.length === 1) return { value: s[0], discarded: null, repeated: false, count: 1 };
    var discarded = s[0];
    var rest = s.slice(1);
    var count = {};
    rest.forEach(function (x) { count[x] = (count[x] || 0) + 1; });
    for (var j = 0; j < rest.length; j++) {
      if (count[rest[j]] >= 2) return { value: rest[j], discarded: discarded, repeated: true, count: count[rest[j]] };
    }
    return { value: rest[0], discarded: discarded, repeated: false, count: 1 };
  }

