    var dr = relsOf(pkg, si.path).filter(function (r) { return /\/drawing$/.test(r.type) && r.path && pkg.has(r.path); })[0];
    if (!dr || !pic || !pic.data) return false;
    var A = areaPx(x, a), k = Math.min(A.w / pic.w, A.h / pic.h), w = pic.w * k, h = pic.h * k, x0 = (A.w - w) / 2, y0 = (A.h - h) / 2;
