    rels.push({ id: rid, type: 'http://schemas.openxmlformats.org/officeDocument/2006/relationships/image', target: relTarget(dr.path, media) });
    pkg.setText(relsPath(dr.path), relsXml(rels.map(function (r) { return { id: r.id, type: r.type, target: r.target, mode: r.mode }; })));
    var dx = pkg.text(dr.path), id = 0, im, ir = /<xdr:cNvPr\b[^>]*\bid="(\d+)"/g;
