    if (!t) return;
    var id = t.id, at = function (n) { return t.getAttribute(n); }, ev = null;
    if (id === 'btnExample') ev = 'example';
    else if (at('data-lang')) ev = t.parentNode && t.parentNode.id === 'langBar' ? 'lang-hint' : 'lang-' + at('data-lang');
    else if (id === 'btnBal') ev = 'balancing';
    else if (id === 'btnLy') ev = 'layout';
    else if (id === 'btnContact' || id === 'btnContactF') ev = 'contact';
    else if (id === 'btnOffline') ev = 'offline-copy';
    else if (id === 'btnNews' || id === 'btnNewsM') ev = 'whats-new';
    else if (at('data-scn') === 'switch') ev = 'scenario-switch';
    else if (at('data-scn') === 'menu') ev = 'scenario-edit';
    else if ((at('data-act') || at('data-ra')) === 'report') ev = 'pdf-report';
    else if ((at('data-act') || at('data-ra')) === 'dlStd') ev = stdForScen() ? 'excel-sheets-sim' : 'excel-sheets';
