  function buildControls() {
    $('speedSeg').innerHTML = SPEEDS.map(function (s) { return '<button type="button" class="btn" data-speed="' + s + '" aria-pressed="false">' + esc(dec1(s)) + '</button>'; }).join('');
    $('zoomSeg').innerHTML = ZOOMS.map(function (z) { return '<button type="button" class="btn" data-zoom="' + z + '" aria-pressed="false">' + esc(T('zoom.' + z)) + '</button>'; }).join('');
    $('speedSel').innerHTML = SPEEDS.map(function (s) { return '<option value="' + s + '">' + esc(dec1(s)) + '\u00d7</option>'; }).join('');
    $('zoomSel').innerHTML = ZOOMS.map(function (z) { return '<option value="' + z + '">' + esc(T('tr.zoom') + ' ' + T('zoom.' + z)) + '</option>'; }).join('');
    updateSpeedUI(); updateZoomUI(); updateMuteUI();
  }

