  var SH = { undo: [], redo: [], ref: null };
  function shState() { return JSON.stringify({ b: study.balance || null, l: study.layout || null }); }
  function shReset() { if (SH.ref !== study) { SH.ref = study; SH.undo = []; SH.redo = []; } }
  function shPush(before) { shReset(); SH.undo.push(before); if (SH.undo.length > 150) SH.undo.shift(); SH.redo = []; }
  function shSnap() { shPush(shState()); }
  function shCan(redo) { shReset(); return (redo ? SH.redo : SH.undo).length > 0; }
  function shMove(from, to) {
    shReset();
    if (!from.length) return false;
    to.push(shState());
    var o = JSON.parse(from.pop());
    study.balance = L.bal.sanitize(o.b);
    study.layout = o.l;
    scSync(); scheduleSave();
    return true;
  }
  function shUndo() { return shMove(SH.undo, SH.redo); }
  function shRedo() { return shMove(SH.redo, SH.undo); }
