      if (withBal) h += '<div class="cr-yama' + (withLy ? '' : ' tall') + '">' + balSvg(two ? [[nm(ref), A], [nm(x), B]] : [[nm(ref), A]], takt, 2900, withLy ? 640 : 980, true, { noKpi: true, chartH: withLy ? 500 : 840, top: 52 }) + '</div>';
      if (withLy && cvs) h += figs(cvs, two ? [nm(ref), nm(x)] : [nm(ref)]) + legend(two ? x : ref);
      if (withBal) h += loadTable(A, B);
