        if (scope === 'bal') { dd = {}; Object.keys(d).forEach(function (k) { dd[k] = d[k]; }); dd.stations = []; }
        h += '<section class="rp-sec cr-blk im-chg"><h2>' + esc(T('balr.whatT')) + '</h2><div class="rp-chgs">' + rpChanges(dd) + '</div></section>';
