  // ---------- Wiring (once, after the start code) ----------
  function balWire() {
    $('btnBal').addEventListener('click', function () { balOpen(!balActive()); });
    window.addEventListener('hashchange', function () {
      var want = location.hash === '#equilibrage';
      if (want !== balActive()) balOpen(want, true);
    });
    var v = $('balView');
    v.addEventListener('click', balClick);
    v.addEventListener('pointerdown', balDown);
    v.addEventListener('pointerover', balOver);
    v.addEventListener('pointerout', balOut);
    v.addEventListener('pointermove', function (e) { if (e.pointerType === 'mouse' && !BS().drag) balTipMove(e.clientX, e.clientY); });
    v.addEventListener('scroll', balTipHide, true);
    var rt = 0;
    window.addEventListener('resize', function () { clearTimeout(rt); rt = setTimeout(function () { if (balActive() && !BS().drag) balRender(); }, 150); });
    $('btnExample').addEventListener('click', exOpen);
    // V5.3: on a first visit the example is offered first (in yellow): its video comes once the page has loaded, unless
    // the connection asks to save data
    window.addEventListener('load', function () {
      var ve = $('videoEmpty'), cn = navigator.connection;
      if (!window.VTS_BASE || !ve || !/\bve-first\b/.test(ve.className) || (cn && (cn.saveData || /2g/.test(cn.effectiveType || '')))) return;
      setTimeout(function () { exEnsure(); }, 1200);
    });
    $('btnFilmTips').addEventListener('click', filmTips);
    // phones and tablets: film the workstation straight from the site (the camera opens, the video comes back here)
    $('btnFilm').addEventListener('click', function () { madeFilm(function () { var i = $('fileCam'); i.value = ''; i.click(); }); });
    // 4.3: the video filmed exists only here: kept in this browser until it is saved
    $('fileCam').addEventListener('change', function (e) { var f = e.target.files && e.target.files[0]; if (f) { track('camera'); madeKeep(f, 'cam'); openVideo(f, { made: 'cam' }); } });
    $('hdrName').addEventListener('input', function () {
      study.meta.name = this.value.slice(0, 120); scheduleSave();
      var f = $('mName'); if (f && f !== document.activeElement) f.value = study.meta.name;
    });
    document.addEventListener('input', function (e) { if (e.target && e.target.id === 'mName') renderHeader(); });
    $('btnMenu').addEventListener('click', function (e) { e.stopPropagation(); menuOpen($('tbDrop').hidden); });
    $('tbDrop').addEventListener('click', function (e) {
      var b = e.target.closest ? e.target.closest('button, a') : null;
      if (b && b.id !== 'btnTheme') setTimeout(function () { menuOpen(false); }, 0);
    });
    document.addEventListener('click', function (e) { if (!$('tbDrop').hidden && !(e.target.closest && e.target.closest('.tb-menu'))) menuOpen(false); });
    document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && !$('tbDrop').hidden) { menuOpen(false); e.stopPropagation(); } }, true);
    $('btnNewStudy').addEventListener('click', openNewStudy);
    document.addEventListener('toggle', function (e) { if (e.target && e.target.classList && e.target.classList.contains('ev-more')) { settings.evOpen = e.target.open; saveSettings(); } }, true);
    $('tab-log').addEventListener('click', function (e) { var b = e.target.closest ? e.target.closest('[data-logexp]') : null; if (b) handleExportAct(b.getAttribute('data-logexp')); });
    updVideoUi();
    $('exBar').addEventListener('click', function (e) {
      var b = e.target.closest ? e.target.closest('[data-ex]') : null;
      if (!b) return;
      var x = b.getAttribute('data-ex');
      if (x === 'res' || x === 'bal' || x === 'ly') { exGo(x); return; }
      if (x === 'own') exOwn(); else if (x === 'quit') exQuit(); else exForget();
    });
    exBar();
    // after the whole script (the layout code runs last): an example from before 4.2 is made again
    setTimeout(function () {
      exUpgrade();
      if (location.hash === '#equilibrage') balOpen(true, true);
      // 4.3: a link to the example (the guide pages): it is offered at once, the address stays clean
      else if (location.hash === '#example' || location.hash === '#exemple') {
        try { history.replaceState(null, '', location.pathname + location.search); } catch (e) { /* not allowed here */ }
        if (!study.example) exOpen();
      }
    }, 0);
  }
