/* LAYOUT-START */
  // ---------- Layout and walking paths (4.0 to 4.2): current layout and scenarios, in 4 guided steps ----------
  // Positions in metres (study.layout, rules in logic.js, L.ly). The current layout is drawn first, then locked:
  // scenarios are copies of it. The plan (a picture, or a DXF drawing read by DXF in dxf.js) stays in this browser
  // (IndexedDB, the last plans used), never in the study file, like the video. The plan is drawn on a canvas under
  // the SVG that holds the stations and the paths.
  var LY = { on: false, step: null, tool: null, sel: null, op: null, ast: null, hov: null, done: false, pend: null, zoom: 30, px: 20, py: 20,
    drag: null, cal: null, cut: null, ptrs: {}, pinch: null, plan: null, fitted: false, undo: [], redo: [], play: false, mult: 1, t0: 0, raf: 0,
    bgKey: '', geo: null, wk: {}, refs: {}, recent: null, busy: false, toolName: null, anyAt: null };
  // one colour per operator on the plans: ten, so that a line of eight operators or more stays readable
  var LY_COLORS = ['#0070C0', '#C00000', '#00B050', '#7030A0', '#ED7D31', '#B8860B', '#00A3A3', '#D6007A', '#1F3B73', '#6B8E23'];
  var LY_KINDS = { post: [1.6, 1], machine: [2.5, 2], rack: [1.2, 0.8], table: [1.4, 0.8] };
  // fill and line of each kind of station, written on the elements too (pictures exported have no style sheet)
  var LY_FILL = { post: ['#DCE6F7', '#2F4FA0'], machine: ['#D9D9D9', '#595959'], rack: ['#FFF0C2', '#B8860B'], table: ['#D6F0DC', '#2E8B57'] };
  var LY_FROM = '#E8890C', LY_TO = '#12803C';
  var LY_STEPS = ['plan', 'posts', 'paths', 'compare'];
  var LY_SIDES = ['f', 'b', 'l', 'r', 'c'];
  var LYG = L.ly;
