  function lyB(a, label, cls, extra) { return '<button type="button" class="btn' + (cls ? ' ' + cls : '') + '" data-ly="' + a + '"' + (extra || '') + '>' + esc(label) + '</button>'; }
  var LY_LOCK_ICON = '<svg class="ly-lk" viewBox="0 0 16 16" aria-hidden="true"><path d="M4 7V5a4 4 0 0 1 8 0v2h1v8H3V7h1zm2 0h4V5a2 2 0 0 0-4 0v2z"/></svg>';
