    var pend = !sc && bsc && !(ly.lock && ly.items.length) ? '<div class="ly-card ly-lockcard"><h4>' + esc(T('ly8.pendT', { name: bsc.name })) + '</h4><p>' + esc(T('ly8.pendTxt')) + '</p></div>' : '';
